div.script:
        let currentUser = null;
        let pusher = null;
        let channel = null;

        // Initialize Pusher
        function initPusher() {
          pusher = new Pusher('a6980257815c1d1d1e6e', {
            cluster: 'eu'
          });

          channel = pusher.subscribe('github-chat');

          channel.bind('message', function(data) {
            addMessage(data);
          });

          channel.bind('user-count', function(data) {
            document.getElementById('online-count').textContent = data.count + ' users online';
          });

          pusher.connection.bind('connected', function() {
            if (!currentUser) {
              document.getElementById('online-count').textContent = 'Connected - Sign in to chat';
            }
          });
        }

        // Open login popup
        function openLoginPopup() {
          const width = 600;
          const height = 700;
          const left = (screen.width - width) / 2;
          const top = (screen.height - height) / 2;
          
          const popup = window.open(
            'https://git-live-chat.vercel.app',
            'GitHub Login',
            `width=${width},height=${height},left=${left},top=${top},resizable=yes,scrollbars=yes`
          );

          // Listen for messages from popup
          window.addEventListener('message', function(event) {
            if (event.origin !== 'https://git-live-chat.vercel.app') return;
            
            if (event.data.type === 'auth-success') {
              currentUser = event.data.user;
              popup.close();
              onLoginSuccess();
            }
          });
        }

        function onLoginSuccess() {
          document.getElementById('login-screen').remove();
          document.getElementById('input-container').style.display = 'block';
          
          const userSection = document.getElementById('user-section');
          userSection.innerHTML = `


              
              @${currentUser.username}
            
          `;

          // Join chat
          fetch('https://git-live-chat.vercel.app/api/join', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              username: currentUser.username,
              avatar: currentUser.image
            })
          });
        }

        function addMessage(msg) {
          const chatBody = document.getElementById('chat-body');
          
          const loginScreen = chatBody.querySelector('.login-screen');
          if (loginScreen) {
            loginScreen.remove();
          }

          const messageDiv = document.createElement('div');
          messageDiv.className = 'message';
          
          const time = new Date(msg.timestamp).toLocaleTimeString('en-US', {
            hour: '2-digit',
            minute: '2-digit'
          });

          const isOwn = currentUser && msg.username === currentUser.username;

          messageDiv.innerHTML = `
            




                @${msg.username}
                ${time}
              

${escapeHtml(msg.text)}
            
          `;

          chatBody.appendChild(messageDiv);
          chatBody.scrollTop = chatBody.scrollHeight;
        }

        function sendMessage() {
          if (!currentUser) return;
          
          const input = document.getElementById('message-input');
          const text = input.value.trim();
          
          if (!text) return;

          fetch('https://git-live-chat.vercel.app/api/messages', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              username: currentUser.username,
              avatar: currentUser.image,
              text: text,
              timestamp: new Date().toISOString()
            })
          });

          input.value = '';
        }

        function escapeHtml(text) {
          const div = document.createElement('div');
          div.textContent = text;
          return div.innerHTML;
        }

        // Enter key to send
        document.addEventListener('DOMContentLoaded', function() {
          const input = document.getElementById('message-input');
          if (input) {
            input.addEventListener('keypress', function(e) {
              if (e.key === 'Enter') {
                sendMessage();
              }
            });
          }
        });

        // Initialize
        initPusher();
